      : ""
  }`;

  useEffect(() => {
    if (scrambleRef.current) {
      scrambleRef.current.textContent = finalText;
    }

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [finalText]);

